#!/usr/bin/env bash
# AKFC — Documentation du schéma Prisma, LOT 3 : médias et stockage.
#   MediaAsset, Folder, FolderLabel, TrashEntry, PageMediaReference, Gallery, GalleryItem
#   + enums FolderStatus, TrashEntryKind, TrashEntryStatus, PageReferencerKind, Visibility.
# Prérequis : lot 2 appliqué.
# Change UNIQUEMENT des commentaires. Preuves exigées avant commit (sinon schéma restauré) :
#   1) schéma sans commentaires strictement identique à l'original ;
#   2) prisma validate ;
#   3) prisma migrate diff ancien → nouveau : VIDE (aucune migration possible) ;
#   4) prisma generate + pnpm check.
# Usage : bash apply-schema-doc-lot3.sh
set -euo pipefail
[ -f "package.json" ] || { echo "ERREUR: racine du repo." >&2; exit 1; }
S="prisma/schema.prisma"
[ -f "$S" ] || { echo "ERREUR: $S introuvable." >&2; exit 1; }
grep -q "Deux usages, cumulables :" "$S" || { echo "ERREUR: applique d'abord le lot 2 (apply-schema-doc-lot2.sh)." >&2; exit 1; }
grep -q "Fichier de la médiathèque (finder), quel que soit son stockage." "$S" && { echo "— déjà appliqué"; exit 0; }

BEFORE=/tmp/akfc_schema_before_lot3.prisma
cp "$S" "$BEFORE"
restore(){ cp "$BEFORE" "$S"; echo "↩ schéma restauré à l'identique."; }

echo '' | base64 -d > /tmp/akfc_lot3_pairs.json
python3 - "$S" <<'PY'
import json, sys
path = sys.argv[1]; s = open(path, encoding="utf-8").read()
data = json.load(open("/tmp/akfc_lot3_pairs.json", encoding="utf-8"))
v1 = False
pairs, mode = (data["upgrade"], "mise à niveau (v1 → v2)") if v1 else (data["fresh"], "application")
for old, new in pairs:
    head = old.split("\n", 1)[0]
    assert s.count(old) == 1, f"bloc « {head} » : trouvé {s.count(old)} fois (le schéma a changé depuis l'archive)"
for old, new in pairs: s = s.replace(old, new)
open(path, "w", encoding="utf-8").write(s)
print(f"  ok  {mode} : {len(pairs)} bloc(s) documenté(s)")
PY

echo "== PREUVE 1 : schéma sans commentaires identique =="
python3 - "$BEFORE" "$S" <<'PY' || { restore; exit 1; }
import sys
def code(path):
    out = []
    for line in open(path, encoding="utf-8"):
        res, q = [], False
        i = 0
        while i < len(line):
            c = line[i]
            if c == '"' and (i == 0 or line[i-1] != "\\"): q = not q
            if not q and line.startswith("//", i): break
            res.append(c); i += 1
        t = " ".join("".join(res).split())
        if t: out.append(t)
    return out
a, b = code(sys.argv[1]), code(sys.argv[2])
if a != b:
    for i, (x, y) in enumerate(zip(a, b)):
        if x != y: print(f"  ❌ 1re différence de code : « {x} » ≠ « {y} »"); break
    else: print(f"  ❌ nombre de lignes de code différent ({len(a)} ≠ {len(b)})")
    sys.exit(1)
print(f"  ✅ {len(a)} lignes de code strictement identiques")
PY

if [ "${AKFC_APPLY_ONLY:-0}" = "1" ]; then echo "APPLY_ONLY"; exit 0; fi

PRISMA(){ pnpm exec prisma "$@" 2>/dev/null || pnpm --filter @workspace/backend exec prisma "$@"; }

echo "== PREUVE 2 : prisma validate =="
PRISMA validate --schema "$S" > /tmp/akfc_v.log 2>&1 || { tail -8 /tmp/akfc_v.log; restore; exit 1; }
echo "  ✅ valide"

echo "== PREUVE 3 : prisma migrate diff (doit être VIDE) =="
set +e
PRISMA migrate diff --from-schema-datamodel "$BEFORE" --to-schema-datamodel "$S" --exit-code > /tmp/akfc_d.log 2>&1
code=$?; set -e
case $code in
  0) echo "  ✅ aucune différence de schéma de base" ;;
  2) echo "  ❌ le diff n'est PAS vide :"; head -20 /tmp/akfc_d.log; restore; exit 1 ;;
  *) echo "  ❌ migrate diff n'a pas pu s'exécuter (code $code) :"; tail -10 /tmp/akfc_d.log; restore; exit 1 ;;
esac

echo "== prisma generate + pnpm check =="
PRISMA generate > /tmp/akfc_g.log 2>&1 || { tail -8 /tmp/akfc_g.log; restore; exit 1; }
if ! pnpm check > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"; grep -nE "conventions Next|error TS|Error:" /tmp/akfc_tc.log | head -15; restore; exit 1
fi
echo "  ✅ check OK"
git add "$S"
git commit -m "docs(prisma): lot 3 — médias et stockage documentés" >/tmp/c.log 2>&1 && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }